<body>
<aside>
  <div class="brand">
    <span class="dot" id="ttsDot" title="TTS server status"></span>
    <h1>Voice Notes</h1>
  </div>
  <div class="controls">
    <input type="search" id="q" placeholder="Filter sessions…" autocomplete="off" />
    <label class="toggle"><input type="checkbox" id="onlyVoice" checked /> only sessions with voice notes</label>
    <label class="toggle">group
      <select class="mini" id="groupMode">
        <option value="dir">by directory</option>
        <option value="cat">by category</option>
      </select>
    </label>
  </div>
  <div class="list" id="sessions"></div>
</aside>

<main>
  <div id="main"><div class="empty">Select a session.</div></div>
</main>

<div class="jump" id="jump" hidden>
  <button id="prevVoice" title="Previous voice note">↑ voice</button>
  <button id="nextVoice" title="Next voice note">↓ voice</button>
  <button id="playAll" title="Play every voice note in order">▶ play all</button>
</div>

<script>
const $ = (id) => document.getElementById(id);
let sessions = [];
let current = null;
let voiceEls = [];
let cursor = -1;

// UI-only metadata (/api/meta): categories + per-session name/category/autoQueue.
let uiMeta = { v: 1, categories: [], sessions: {} };
// Latest /api/status payload, keyed by session id. Never triggers a timeline render.
let statusMap = {};
// "none" | "final" | "every" — how much the user's global voice config already voices.
let voiceCoverage = "final";
// Source-response disclosures the user has expanded, by source entry id, for the open session.
let openGroups = new Set();
// Session id whose sidebar row is being renamed inline; suppresses background re-renders.
let renaming = null;
let toastTimer = null;

const fmtTime = (ts) => {
  const d = new Date(ts);
  return isNaN(d) ? "" : d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
};
const fmtDate = (ts) => {
  const d = new Date(ts);
  return isNaN(d) ? "" : d.toLocaleString([], { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
};
const fmtDur = (ms) => (ms == null ? "" : `${(ms / 1000).toFixed(1)}s`);
const fmtSize = (b) => (b == null ? "" : b < 1024 ? `${b} B` : `${(b / 1024).toFixed(0)} KB`);
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

// ── Pure view logic (no DOM; unit-tested from node) ────────

const shortPath = (p) => String(p ?? "").replace(/^\/Users\/[^/]+/, "~");
const wordCount = (s) => (String(s ?? "").match(/\S+/g) || []).length;
// The override wins over the transcript-derived title everywhere the session is named.
const displayNameOf = (s) => (s && s.name && s.name.trim()) || (s && s.title) || "(untitled)";
// Category colours land in a style attribute, and the server stores whatever was POSTed,
// so only accept literal colours here — esc() stops quote-breaking but not `red;background:url(…)`.
const safeColor = (c) => (/^#[0-9a-fA-F]{3,8}$/.test(String(c ?? "").trim()) ? String(c).trim() : null);

const PHASES = ["idle", "summarizing", "speaking", "archiving"];
// `idle` is worth showing: it is how the user tells which sessions are open at all.
const PHASE_LABEL = { idle: "open", summarizing: "summarizing", speaking: "speaking", archiving: "archiving" };

function phaseInfo(st) {
  if (!st) return null;
  const phase = PHASES.includes(st.phase) ? st.phase : "idle";
  const stalled = !!st.stalled;
  const detail = st.detail ? String(st.detail) : "";
  const queueDepth = Number(st.queueDepth) || 0;
  const title = stalled
    ? `stuck in "${phase}" — the pi process (pid ${st.pid}) is still alive but has reported no progress since ${fmtTime(st.updatedAt)}, so it looks wedged`
    : [`${phase}${detail ? ` — ${detail}` : ""}`, `pid ${st.pid}`, `updated ${fmtTime(st.updatedAt)}`].join(" · ");
  return {
    phase, stalled, detail, queueDepth,
    label: PHASE_LABEL[phase],
    cls: `stat p-${phase}${stalled ? " stalled" : ""}`,
    title,
  };
}

// Bucket sessions for the sidebar. `mode` is "dir" (default) or "cat".
function groupSessions(list, mode, categories) {
  const byId = new Map((categories || []).map((c) => [c.id, c]));
  const map = new Map();
  for (const s of list) {
    let key, label, color = null, mono = false;
    if (mode === "cat") {
      const c = s.categoryId ? byId.get(s.categoryId) : null;
      key = c ? `cat:${c.id}` : "cat:none";
      label = c ? c.name : "Uncategorized";
      color = c ? c.color : null;
    } else {
      key = `dir:${s.cwd ?? ""}`;
      label = shortPath(s.cwd) || "(no directory)";
      mono = true;
    }
    let g = map.get(key);
    if (!g) map.set(key, (g = { key, label, color, mono, sessions: [], last: 0 }));
    g.sessions.push(s);
    g.last = Math.max(g.last, s.mtimeMs || Date.parse(s.updatedAt) || 0);
  }
  // Most-recently-active group first; "Uncategorized" is a leftovers bin, so it sinks.
  return [...map.values()].sort((a, b) => {
    if (a.key === "cat:none") return 1;
    if (b.key === "cat:none") return -1;
    return b.last - a.last;
  });
}

// Fold the flat chronological timeline into render nodes, pairing each voice note with the
// assistant message it summarizes. Returns {type:"item"} and {type:"group"} nodes in order.
// A grouped assistant message is emitted only inside its group — never standalone as well.
function pairTimeline(items) {
  const assistants = new Map();
  for (const it of items) if (it.kind === "assistant") assistants.set(it.id, it);

  const notesBySource = new Map();
  for (const it of items) {
    if (it.kind !== "voice") continue;
    const sid = it.sourceEntryId;
    if (!sid || !assistants.has(sid)) continue;
    if (!notesBySource.has(sid)) notesBySource.set(sid, []);
    notesBySource.get(sid).push(it);
  }

  const out = [];
  const done = new Set();
  for (const it of items) {
    if (it.kind === "assistant" && notesBySource.has(it.id)) continue;
    if (it.kind === "voice") {
      const sid = it.sourceEntryId;
      if (sid && notesBySource.has(sid)) {
        // Several notes can share one source; they stack into the single group, placed at
        // the first note's position so the timeline stays chronological.
        if (done.has(sid)) continue;
        done.add(sid);
        out.push({ type: "group", key: sid, source: assistants.get(sid), notes: notesBySource.get(sid) });
        continue;
      }
    }
    out.push({ type: "item", item: it });
  }
  return out;
}

// Honest description of what auto-queue will actually do, given the global voice config.
function autoQueueNote(coverage) {
  if (coverage === "every") {
    return {
      caution: true,
      text: "every response is already voiced by your global voice config — this adds nothing right now",
    };
  }
  if (coverage === "none") {
    return {
      caution: false,
      text: "nothing is voiced automatically right now, so auto-queue does all the work for this session",
    };
  }
  return {
    caution: false,
    text: "only the final response of each run is voiced today — auto-queue fills in the earlier ones",
  };
}

if (typeof module === "object" && module.exports) {
  module.exports = { esc, shortPath, wordCount, displayNameOf, safeColor, phaseInfo, groupSessions, pairTimeline, autoQueueNote };
}

// ── Persisted sidebar preferences ──────────────────────────

const LS_GROUP = "va.groupMode";
const LS_COLLAPSED = "va.collapsedGroups";

const groupMode = () => (localStorage.getItem(LS_GROUP) === "cat" ? "cat" : "dir");

let collapsed = new Set();
try { collapsed = new Set(JSON.parse(localStorage.getItem(LS_COLLAPSED) || "[]")); } catch { /* corrupt ⇒ all open */ }
const saveCollapsed = () => { try { localStorage.setItem(LS_COLLAPSED, JSON.stringify([...collapsed])); } catch { /* private mode */ } };

function toast(msg) {
  let el = $("toast");
  if (!el) { el = document.createElement("div"); el.id = "toast"; el.className = "toast"; document.body.append(el); }
  el.textContent = msg;
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.remove(), 4000);
}

// ── Sidebar ────────────────────────────────────────────────

async function loadMeta() {
  try {
    const res = await fetch("/api/meta");
    if (res.ok) uiMeta = await res.json();
  } catch { /* keep whatever we had */ }
}

async function loadSessions() {
  const res = await fetch(`/api/sessions${$("onlyVoice").checked ? "?voice=1" : ""}`);
  sessions = await res.json();
  renderSessions();
}

function renderSessions() {
  const box = $("sessions");
  const scroll = box.scrollTop;
  const q = $("q").value.toLowerCase().trim();
  const shown = q
    ? sessions.filter((s) => `${displayNameOf(s)} ${s.title} ${s.cwd}`.toLowerCase().includes(q))
    : sessions;

  if (!shown.length) {
    box.innerHTML = `<div class="empty" style="padding:30px 6px;font-size:12px">No sessions.</div>`;
    return;
  }

  box.innerHTML = groupSessions(shown, groupMode(), uiMeta.categories).map(groupHTML).join("");
  wireSidebar();
  applyStatus();
  box.scrollTop = scroll;
}

function groupHTML(g) {
  const open = !collapsed.has(g.key);
  const color = safeColor(g.color);
  return `
    <div class="grp">
      <button class="grph" data-grp="${esc(g.key)}" aria-expanded="${open}" title="${esc(g.label)}">
        <span class="caret">${open ? "▾" : "▸"}</span>
        ${color ? `<span class="catdot" style="background:${esc(color)}"></span>` : ""}
        <span class="gl${g.mono ? " mono" : ""}">${esc(g.label)}</span>
        <span class="gc">${g.sessions.length}</span>
      </button>
      ${open ? g.sessions.map(sessHTML).join("") : ""}
    </div>`;
}

function sessHTML(s) {
  const overridden = !!(s.name && s.name.trim());
  const cat = (uiMeta.categories || []).find((c) => c.id === s.categoryId) || null;
  const catColor = cat ? safeColor(cat.color) : null;
  return `
    <div class="sess ${s.id === current?.meta.id ? "active" : ""}" data-id="${esc(s.id)}" title="${esc(overridden ? s.title : "")}">
      <div class="t" data-title="1">${esc(displayNameOf(s))}</div>
      ${overridden ? `<div class="subtitle">${esc(s.title)}</div>` : ""}
      <div class="m">
        <span>${fmtDate(s.updatedAt)}</span>
        ${s.voiceNotes ? `<span class="pill">♪ ${s.voiceNotes}</span>` : ""}
        <span>${s.messages} msg</span>
        <span data-stat="${esc(s.id)}"></span>
      </div>
      <div class="m">
        <span class="cwd">${esc(shortPath(s.cwd))}</span>
        ${cat ? `<span class="catchip"${catColor ? ` style="color:${esc(catColor)}"` : ""}>${esc(cat.name)}</span>` : ""}
      </div>
      <div class="ctl">
        <button data-rename="${esc(s.id)}" title="Rename in this UI only — the session file is never touched">✎ rename</button>
        <select class="mini" data-cat="${esc(s.id)}" title="Category">${catOptionsHTML(s.categoryId)}</select>
      </div>
    </div>`;
}

function catOptionsHTML(selected) {
  const opts = [`<option value=""${!selected ? " selected" : ""}>Uncategorized</option>`];
  for (const c of uiMeta.categories || []) {
    opts.push(`<option value="${esc(c.id)}"${c.id === selected ? " selected" : ""}>${esc(c.name)}</option>`);
  }
  opts.push(`<option value="__new">New category…</option>`);
  return opts.join("");
}

function wireSidebar() {
  for (const el of document.querySelectorAll(".sess")) {
    el.onclick = (e) => { if (!e.target.closest(".ctl") && !e.target.closest("input.rename")) openSession(el.dataset.id); };
  }
  for (const b of document.querySelectorAll("[data-grp]")) {
    b.onclick = () => {
      const key = b.dataset.grp;
      if (collapsed.has(key)) collapsed.delete(key); else collapsed.add(key);
      saveCollapsed();
      renderSessions();
    };
  }
  for (const b of document.querySelectorAll("[data-rename]")) {
    b.onclick = (e) => { e.stopPropagation(); startRename(b.dataset.rename); };
  }
  for (const sel of document.querySelectorAll("[data-cat]")) {
    sel.onclick = (e) => e.stopPropagation();
    sel.onchange = (e) => { e.stopPropagation(); pickCategory(sel.dataset.cat, sel.value); };
  }
}

const rowFor = (id) => [...document.querySelectorAll(".sess")].find((el) => el.dataset.id === id);

// ── Renaming + categorizing (§3) ───────────────────────────

function startRename(id) {
  const row = rowFor(id);
  const s = sessions.find((x) => x.id === id);
  if (!row || !s) return;
  const slot = row.querySelector("[data-title]");
  if (!slot || slot.dataset.editing) return;

  renaming = id;
  const input = document.createElement("input");
  input.className = "rename";
  input.value = s.name || "";
  input.placeholder = s.title || "";
  const finish = (commit) => {
    if (renaming !== id) return;
    renaming = null;
    // An empty value clears the override and falls back to the derived title.
    if (commit) patchSessionMeta(id, { name: input.value.trim() });
    else renderSessions();
  };
  input.onkeydown = (e) => {
    e.stopPropagation();
    if (e.key === "Enter") { e.preventDefault(); finish(true); }
    else if (e.key === "Escape") { e.preventDefault(); finish(false); }
  };
  input.onblur = () => finish(false);
  slot.dataset.editing = "1";
  slot.replaceChildren(input);
  input.focus();
  input.select();
}

async function pickCategory(id, value) {
  if (value !== "__new") { patchSessionMeta(id, { categoryId: value || null }); return; }
  const name = prompt("New category name:");
  if (name == null || !name.trim()) { renderSessions(); return; }
  try {
    const res = await fetch("/api/categories", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ name: name.trim() }),
    });
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? res.statusText);
    const cat = await res.json();
    await loadMeta();
    await patchSessionMeta(id, { categoryId: cat.id });
  } catch (err) {
    toast(`could not create category: ${err.message}`);
    renderSessions();
  }
}

// Patch and then reconcile in place — reloading the list from scratch would throw away the
// user's scroll position and which groups they had open.
async function patchSessionMeta(id, patch) {
  try {
    const res = await fetch(`/api/session/${encodeURIComponent(id)}/meta`, {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(patch),
    });
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? res.statusText);
    const next = await res.json();
    uiMeta.sessions = uiMeta.sessions || {};
    uiMeta.sessions[id] = { name: next.name, categoryId: next.categoryId, autoQueue: next.autoQueue };
    const s = sessions.find((x) => x.id === id);
    if (s) Object.assign(s, { name: next.name, categoryId: next.categoryId, autoQueue: next.autoQueue, displayName: displayNameOf({ ...s, name: next.name }) });
    if (current?.meta.id === id) {
      Object.assign(current.meta, { name: next.name, categoryId: next.categoryId, autoQueue: next.autoQueue });
      refreshHeaderMeta();
    }
  } catch (err) {
    toast(`update failed: ${err.message}`);
  }
  renderSessions();
}

// ── Session view ───────────────────────────────────────────

async function openSession(id) {
  const res = await fetch(`/api/session/${encodeURIComponent(id)}`);
  if (!res.ok) return;
  current = await res.json();
  openGroups = new Set(); // expansion state is per-session and may reset on switch
  renderSession();
  renderSessions();
  location.hash = id;
}

function renderSession() {
  const { meta, items } = current;
  const notes = items.filter((i) => i.kind === "voice");
  const audioCount = notes.filter((n) => n.audio).length;
  const overridden = !!(meta.name && meta.name.trim());
  const aq = autoQueueNote(voiceCoverage);

  const head = `
    <div class="head">
      <h2 id="headName">${esc(displayNameOf(meta))}</h2>
      <div class="subtitle" id="headSub" ${overridden ? "" : "hidden"}>${esc(meta.title)}</div>
      <div class="m">
        <span>${fmtDate(meta.startedAt)}</span>
        <span class="cwd">${esc(shortPath(meta.cwd))}</span>
        <span>${notes.length} voice note${notes.length === 1 ? "" : "s"} · ${audioCount} playable</span>
        <span data-stat="${esc(meta.id)}" data-big="1"></span>
      </div>
      <div class="aq">
        <label class="toggle" title="Summarize and archive every response in this session as a voice note. Nothing is played aloud — the notes go straight to the archive for you to browse later.">
          <input type="checkbox" id="autoQueue" ${meta.autoQueue ? "checked" : ""} /> auto-queue every response
        </label>
        <span class="note${aq.caution ? " caution" : ""}">${esc(aq.text)}</span>
      </div>
    </div>`;

  const body = pairTimeline(items).map(renderNode).join("");
  $("main").innerHTML = head + `<div class="body">${body || '<div class="empty">Nothing recorded.</div>'}</div>`;

  voiceEls = [...document.querySelectorAll('[data-voice="1"]')];
  cursor = -1;
  $("jump").hidden = voiceEls.length === 0;

  for (const btn of document.querySelectorAll("[data-speak]")) {
    btn.onclick = () => speak(btn);
  }
  for (const d of document.querySelectorAll("details.src")) {
    d.addEventListener("toggle", () => {
      if (d.open) openGroups.add(d.dataset.src); else openGroups.delete(d.dataset.src);
    });
  }
  $("autoQueue").onchange = (e) => patchSessionMeta(current.meta.id, { autoQueue: e.target.checked });
  applyStatus();
  document.querySelector("main").scrollTop = 0;
}

// Header bits that a PATCH can change, updated in place so the timeline survives.
function refreshHeaderMeta() {
  const { meta } = current;
  const name = $("headName");
  const sub = $("headSub");
  const box = $("autoQueue");
  if (name) name.textContent = displayNameOf(meta);
  if (sub) { sub.textContent = meta.title ?? ""; sub.hidden = !(meta.name && meta.name.trim()); }
  if (box) box.checked = !!meta.autoQueue;
}

function renderNode(node) {
  return node.type === "group" ? renderGroup(node) : renderItem(node.item);
}

// One card: the voice note(s) on top, the response they summarize collapsed underneath.
function renderGroup(g) {
  const words = wordCount(g.source.text);
  const open = openGroups.has(g.key);
  const label = g.notes.length === 1 ? "♪ voice note" : `♪ ${g.notes.length} voice notes`;
  return `
    <div class="item">
      <div class="gutter">${fmtTime(g.notes[0].ts)}</div>
      <div>
        <div class="who voice">${label}</div>
        <div class="card">
          ${g.notes.map((n) => `<div class="vnote" data-voice="1">${voiceBody(n)}</div>`).join("")}
