// Headless unit tests for ui.html's pure view logic, run against REAL server payloads.
import { readFileSync } from "node:fs";

const BASE = "http://127.0.0.1:8193";
const html = readFileSync(
  "/Users/michael.schmitt/projects/dotfiles/pi/.pi/agent/extensions/voice-archive/ui.html",
  "utf8",
);
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
// The pure, DOM-free half of the script: everything before the localStorage section.
const cut = script.indexOf("// ── Persisted sidebar preferences");
if (cut < 0) throw new Error("marker not found — pure section moved");
const pure = script.slice(0, cut);

const names = ["esc", "shortPath", "wordCount", "displayNameOf", "safeColor", "phaseInfo",
  "groupSessions", "pairTimeline", "autoQueueNote", "voiceBody", "assistantBody"];
// eslint-disable-next-line no-new-func
const load = new Function(`${pure}\nreturn {${names.filter((n) => pure.includes(`function ${n}`) || pure.includes(`${n} =`)).join(",")}};`);
const U = load();

const get = (p) => fetch(BASE + p).then((r) => r.json());
let fails = 0;
const check = (name, cond, extra = "") => {
  console.log(`${cond ? "PASS" : "FAIL"}  ${name}${extra ? `  ${extra}` : ""}`);
  if (!cond) fails++;
};

// ── (a) pairing on the fixture ─────────────────────────────
const fix = await get("/api/session/fixture0-aaaa-bbbb-cccc-000000000001");
const nodes = U.pairTimeline(fix.items);
console.log("\n=== (a) pairTimeline(fixture) ===");
for (const n of nodes) {
  if (n.type === "group") {
    console.log(`group  key=${n.key}  source=${n.source.id}  notes=[${n.notes.map((x) => x.noteId).join(",")}]  words=${U.wordCount(n.source.text)}`);
  } else {
    console.log(`item   kind=${n.item.kind}  id=${n.item.id}`);
  }
}
const groups = nodes.filter((n) => n.type === "group");
const standalone = nodes.filter((n) => n.type === "item").map((n) => n.item);
check("n1 pairs to a1", groups.some((g) => g.key === "a1" && g.notes.map((x) => x.noteId).join() === "n1"));
check("n2 pairs to a2", groups.some((g) => g.key === "a2" && g.notes.map((x) => x.noteId).join() === "n2"));
check("a1 not rendered standalone", !standalone.some((i) => i.id === "a1"));
check("a2 not rendered standalone", !standalone.some((i) => i.id === "a2"));
check("v1/v2 not rendered standalone", !standalone.some((i) => i.kind === "voice"));
check("users still standalone", standalone.filter((i) => i.kind === "user").length === 2);
check("node count = 4 (u1, group a1, u2, group a2)", nodes.length === 4, `got ${nodes.length}`);
check("chronological order preserved",
  nodes.map((n) => (n.type === "group" ? n.notes[0].ts : n.item.ts)).every((ts, i, a) => i === 0 || a[i - 1] <= ts));

// ── regression: a real 91-message session with unpaired notes ──
const real = await get("/api/session/019fd2c6-595f-7b7b-bd25-3cf55d4e36fa");
const realNodes = U.pairTimeline(real.items);
const realVoices = real.items.filter((i) => i.kind === "voice");
console.log("\n=== regression: real session ===");
console.log(`items=${real.items.length} nodes=${realNodes.length} voiceNotes=${realVoices.length} groups=${realNodes.filter((n) => n.type === "group").length}`);
check("no items lost when nothing pairs", realNodes.length === real.items.length);
check("every voice note still rendered",
  realNodes.filter((n) => n.type === "item" && n.item.kind === "voice").length === realVoices.length);

// ── multiple notes sharing one source ──────────────────────
const shared = U.pairTimeline([
  { kind: "assistant", id: "a", ts: "1", text: "one two three", tools: [], voiceNoteIds: ["x", "y"] },
  { kind: "voice", id: "v1", noteId: "x", ts: "2", text: "n1", sourceEntryId: "a" },
  { kind: "voice", id: "v2", noteId: "y", ts: "3", text: "n2", sourceEntryId: "a" },
]);
console.log("\n=== two notes, one source ===");
console.log(JSON.stringify(shared.map((n) => (n.type === "group" ? { g: n.key, notes: n.notes.map((x) => x.noteId) } : n.item.id))));
check("both notes stack into one group", shared.length === 1 && shared[0].notes.length === 2);

// ── dangling sourceEntryId (source not in this timeline) ────
const dangling = U.pairTimeline([{ kind: "voice", id: "v", noteId: "z", ts: "1", text: "t", sourceEntryId: "missing" }]);
check("unknown sourceEntryId falls back to standalone", dangling.length === 1 && dangling[0].type === "item");

// ── (b) directory grouping over all sessions ───────────────
const all = await get("/api/sessions");
const dirs = U.groupSessions(all, "dir", []);
console.log(`\n=== (b) groupSessions(dir) — ${all.length} sessions → ${dirs.length} groups ===`);
for (const g of dirs.slice(0, 12)) console.log(`  ${String(g.sessions.length).padStart(3)}  ${g.label}${g.mono ? "" : " (!mono)"}`);
console.log(`  … ${Math.max(0, dirs.length - 12)} more groups`);
check("every session bucketed exactly once", dirs.reduce((n, g) => n + g.sessions.length, 0) === all.length);
check("directory labels use ~", dirs.every((g) => !g.label.startsWith("/Users/")));
check("groups sorted most-recently-active first",
  dirs.every((g, i) => i === 0 || dirs[i - 1].last >= g.last));
check("newest session is in the first group", dirs[0].sessions.some((s) => s.id === all[0].id));

// ── category grouping, incl. Uncategorized sinking ─────────
const meta = await get("/api/meta");
const tagged = all.map((s, i) => (i % 50 === 0 ? { ...s, categoryId: meta.categories[i % meta.categories.length]?.id ?? null } : s));
const cats = U.groupSessions(tagged, "cat", meta.categories);
console.log("\n=== groupSessions(cat) ===");
for (const g of cats) console.log(`  ${String(g.sessions.length).padStart(3)}  ${g.key}  ${JSON.stringify(g.label)}  color=${JSON.stringify(g.color)}→safe=${JSON.stringify(U.safeColor(g.color))}`);
check("Uncategorized sorts last", cats[cats.length - 1].key === "cat:none");
check("all sessions bucketed in category mode", cats.reduce((n, g) => n + g.sessions.length, 0) === all.length);

// ── (c) status → label / colour class ──────────────────────
console.log("\n=== (c) phaseInfo ===");
const fixtureStatus = {
  phase: "summarizing", detail: "Fixture is pretending to summarize a response",
  queueDepth: 2, pid: 4242, cwd: "/x", updatedAt: "2026-08-05T17:40:53.000Z", stalled: false,
};
for (const st of [
  fixtureStatus,
  { ...fixtureStatus, phase: "speaking", queueDepth: 0, detail: "" },
  { ...fixtureStatus, phase: "archiving" },
  { ...fixtureStatus, phase: "idle", detail: "", queueDepth: 0 },
  { ...fixtureStatus, stalled: true },
  { ...fixtureStatus, phase: "bogus-phase" },
]) {
  const p = U.phaseInfo(st);
  console.log(`  in=${String(st.phase).padEnd(13)} stalled=${st.stalled ? "y" : "n"} → cls=${JSON.stringify(p.cls)} label=${JSON.stringify(p.label)} q=${p.queueDepth}`);
}
const fp = U.phaseInfo(fixtureStatus);
check("summarizing → p-summarizing class", fp.cls === "stat p-summarizing");
check("summarizing → label 'summarizing'", fp.label === "summarizing");
check("queueDepth surfaced", fp.queueDepth === 2);
check("detail surfaced", fp.detail.startsWith("Fixture is pretending"));
check("idle → non-pulsing p-idle class", U.phaseInfo({ ...fixtureStatus, phase: "idle" }).cls === "stat p-idle");
check("stalled adds .stalled", U.phaseInfo({ ...fixtureStatus, stalled: true }).cls.endsWith(" stalled"));
check("stalled title explains wedge", /looks wedged/.test(U.phaseInfo({ ...fixtureStatus, stalled: true }).title));
check("unknown phase degrades to idle", U.phaseInfo({ ...fixtureStatus, phase: "bogus-phase" }).phase === "idle");
check("no status → no indicator", U.phaseInfo(undefined) === null);

// ── real /api/status shape ─────────────────────────────────
const live = await get("/api/status");
console.log("\n=== live /api/status through phaseInfo ===");
for (const [id, st] of Object.entries(live.sessions)) {
  const p = U.phaseInfo(st);
  console.log(`  ${id}  ${p.cls.padEnd(24)} ${p.label.padEnd(12)} q=${p.queueDepth} detail=${JSON.stringify(p.detail)}`);
}

// ── (d) escaping proof ─────────────────────────────────────
console.log("\n=== (d) escaping ===");
const XSS = '<img src=x onerror=alert(1)>';
console.log("  esc(session name):  ", U.esc(XSS));
console.log("  esc(category name): ", U.esc(meta.categories.map((c) => c.name).find((n) => n.includes("<")) ?? XSS));
check("angle brackets escaped", !U.esc(XSS).includes("<") && U.esc(XSS).includes("&lt;"));
check("quotes escaped (attribute safety)", U.esc('a"b\'c').includes("&quot;") && U.esc('a"b\'c').includes("&#39;"));
const evilColor = meta.categories.find((c) => String(c.color).includes(";"))?.color ?? "red;background:url(http://evil/x)";
console.log(`  safeColor(${JSON.stringify(evilColor)}) = ${JSON.stringify(U.safeColor(evilColor))}`);
check("css-injecting colour rejected", U.safeColor(evilColor) === null);
check("literal hex colour kept", U.safeColor("#7aa2f7") === "#7aa2f7");
