const grab = (name) => script.match(new RegExp(`function ${name}\\([^)]*\\) \\{[\\s\\S]*?\\n\\}`))[0];
const renderSrc = ["renderNode", "renderGroup", "voiceBody", "assistantBody", "renderItem", "statusHTML"].map(grab).join("\n");

const mk = new Function("openGroups", `${pure}\n${renderSrc}\nreturn {renderNode, statusHTML, pairTimeline, wordCount};`);

const fix = await fetch("http://127.0.0.1:8193/api/session/fixture0-aaaa-bbbb-cccc-000000000001").then((r) => r.json());
let fails = 0;
const check = (n, c) => { console.log(`${c ? "PASS" : "FAIL"}  ${n}`); if (!c) fails++; };

for (const opened of [new Set(), new Set(["a1"])]) {
  const R = mk(opened);
  const out = R.pairTimeline(fix.items).map(R.renderNode).join("");
  console.log(`\n================ openGroups=${JSON.stringify([...opened])} ================`);
  console.log(out.replace(/\n\s*\n/g, "\n").trim());

  const count = (re) => (out.match(re) || []).length;
  check("2 groups rendered as details.src", count(/<details class="src"/g) === 2);
  check("4 data-voice=1 anchors? no — 2 notes", count(/data-voice="1"/g) === 2);
  check("a1 text appears exactly once", count(/The refresh token was expiring early/g) === 1);
  check("a2 text appears exactly once", count(/Committed as 4f2ab1/g) === 1);
  check("both notes have an <audio> player", count(/<audio controls/g) === 2);
  check("audio urls are session-prefixed", count(/src="\/api\/audio\/fixture0-aaaa-bbbb-cccc-000000000001\//g) === 2);
  check("source word counts rendered", /source response \(17 words\)/.test(out) && /source response \(10 words\)/.test(out));
  check("♪ read aloud survives inside the disclosure", count(/♪ read aloud/g) === 2);
  check("queue-sourced note labelled", /auto-queued/.test(out));
  check("no standalone assistant .item", count(/<div class="item assistant"/g) === 0);
  check("2 user items still standalone", count(/<div class="item user"/g) === 2);
  check(`a1 disclosure ${opened.has("a1") ? "open" : "collapsed"}`,
    /<details class="src" data-src="a1" open>/.test(out) === opened.has("a1"));
  check("a2 disclosure always collapsed by default", /<details class="src" data-src="a2">/.test(out));
  check("no unbalanced tags (rough)", (out.match(/<div/g) || []).length === (out.match(/<\/div>/g) || []).length);
}

// Header/sidebar status markup, big and small.
const R = mk(new Set());
const st = { phase: "summarizing", detail: "Fixture is pretending to summarize a response", queueDepth: 2, pid: 4242, updatedAt: "2026-08-05T17:40:53.000Z", stalled: false };
console.log("\n=== statusHTML(small, sidebar) ===\n" + R.statusHTML(st, false));
console.log("\n=== statusHTML(big, header) ===\n" + R.statusHTML(st, true));
console.log("\n=== statusHTML(stalled) ===\n" + R.statusHTML({ ...st, stalled: true }, true));
console.log("\n=== statusHTML(idle) ===\n" + R.statusHTML({ ...st, phase: "idle", detail: "", queueDepth: 0 }, false));
console.log("\n=== statusHTML(no status) ===\n" + JSON.stringify(R.statusHTML(undefined, false)));
check("header status shows detail", R.statusHTML(st, true).includes("Fixture is pretending"));
check("header status shows queue depth", R.statusHTML(st, true).includes("queue 2"));
check("sidebar status omits detail/queue", !R.statusHTML(st, false).includes("queue 2"));
check("stalled marked with ⚠", R.statusHTML({ ...st, stalled: true }, true).includes("⚠"));
const evilDetail = R.statusHTML({ ...st, detail: '<img src=x onerror=alert(1)>' }, true);
console.log("\n=== statusHTML with hostile detail (status files are on disk, escape anyway) ===\n" + evilDetail);
check("hostile detail escaped", !/<img/i.test(evilDetail));

console.log(`\n${fails === 0 ? "ALL RENDER CHECKS PASSED" : `${fails} RENDER CHECK(S) FAILED`}`);
process.exit(fails ? 1 : 0);
"
}

