async function patchSessionMeta(id, patch) {
  try {
    const res = await fetch(`/api/session/${encodeURIComponent(id)}/meta`, {
      method: "PATCH",
      headers: { "content-type": "application/json" },
      body: JSON.stringify(patch),
    });
    if (!res.ok) throw new Error((await res.json().catch(() => ({}))).error ?? res.statusText);
    const next = await res.json();
    const s = sessions.find((x) => x.id === id);
    if (s) Object.assign(s, { name: next.name, categoryId: next.categoryId, autoQueue: next.autoQueue, displayName: displayNameOf({ ...s, name: next.name }) });
    if (current?.meta.id === id) {
      Object.assign(current.meta, { name: next.name, categoryId: next.categoryId, autoQueue: next.autoQueue });
      refreshHeaderMeta();
    }
  } catch (err) {
    toast(`update failed: ${err.message}`);
  }
  renderSessions();
}
